//! The MCP read surface, derived from one artifact (`packages/sdk/mcp-catalog.json`,
//! generated by `scripts/gen-mcp-catalog.mjs` from the OpenAPI snapshot and the
//! authored policy). The tool catalog and the org's capability registry both
//! read THIS, so the adapter and the server cannot disagree about what exists.
//!
//! These names are not API-key scopes. A catalog capability authorizes an MCP
//! tool through the grant registry, and the caller's own session authorizes
//! the proxied read; minting the name onto an API key produced a credential
//! that authenticated with no permission behind it (F95). A key mints only
//! [`crate::api_scopes`], which is the vocabulary the resolver actually maps.

use serde::Deserialize;
use std::sync::OnceLock;

const CATALOG_JSON: &str = include_str!("../../../packages/sdk/mcp-catalog.json");

#[derive(Debug, Clone, Deserialize)]
pub struct CatalogTool {
    pub name: String,
    pub path: String,
    pub capability: String,
    #[serde(default)]
    pub summary: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct CatalogFamily {
    pub namespace: String,
    pub capability: String,
    #[serde(default)]
    pub sensitive: bool,
    pub tools: Vec<CatalogTool>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct SensitiveCapability {
    pub capability: String,
    pub namespace: String,
    pub paths: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct Catalog {
    version: u32,
    families: Vec<CatalogFamily>,
    #[serde(default)]
    sensitive_capabilities: Vec<SensitiveCapability>,
}

fn catalog() -> &'static Catalog {
    static CATALOG: OnceLock<Catalog> = OnceLock::new();
    CATALOG.get_or_init(|| {
        let parsed: Catalog =
            serde_json::from_str(CATALOG_JSON).expect("mcp-catalog.json is generated and valid");
        assert_eq!(
            parsed.version, 1,
            "mcp-catalog.json version {} is newer than this reader understands",
            parsed.version
        );
        parsed
    })
}

/// Every family in the derived catalog, sorted by namespace (the admin surface
/// renders this order).
pub fn families() -> &'static [CatalogFamily] {
    &catalog().families
}

/// Sensitive sub-capabilities: reads inside a family that a family grant must
/// NOT imply (ticket correspondence today). Each is grantable on its own.
pub fn sensitive_capabilities() -> &'static [SensitiveCapability] {
    &catalog().sensitive_capabilities
}

/// A capability an MCP admin may hold: a family's `:read`, a declared
/// sensitive sub-capability, or a family's `:write`. The write dial does not
/// expose MCP tools (this release has none); it gates the IF8 proposal
/// pipeline — the agent's authored change is admitted under the dial and
/// still applies only through approval. What it cannot be is a namespace the
/// catalog does not know: that is the dead-grant class row A29 closes.
pub fn is_grantable(capability: &str) -> bool {
    if catalog()
        .sensitive_capabilities
        .iter()
        .any(|s| s.capability == capability)
    {
        return true;
    }
    let Some((ns, action)) = capability.rsplit_once(':') else {
        return false;
    };
    matches!(action, "read" | "write")
        && catalog()
            .families
            .iter()
            .any(|f| f.namespace == ns && f.capability == format!("{ns}:read"))
}

fn path_matches(pattern: &str, candidate: &[&str]) -> bool {
    let segments: Vec<&str> = pattern.trim_matches('/').split('/').collect();
    if segments.len() != candidate.len() {
        return false;
    }
    segments.iter().zip(candidate).all(|(p, c)| {
        if p.starts_with('{') && p.ends_with('}') {
            !c.is_empty()
        } else {
            p == c
        }
    })
}

/// The capability that governs one concrete request path, for diagnostics and
/// the admin surface: the family read capability, or the sensitive
/// sub-capability when the path is one of its declared reads.
pub fn capability_for_path(path: &str) -> Option<&'static str> {
    let candidate: Vec<&str> = path.trim_matches('/').split('/').collect();
    for family in &catalog().families {
        for tool in &family.tools {
            if path_matches(&tool.path, &candidate) {
                return Some(tool.capability.as_str());
            }
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_parses_and_has_the_derived_surface() {
        let families = families();
        assert!(
            families.len() >= 80,
            "the derived surface is broad (got {})",
            families.len()
        );
        let tools: usize = families.iter().map(|f| f.tools.len()).sum();
        assert!(
            tools >= 250,
            "every allowed family read is a tool (got {tools})"
        );
    }

    #[test]
    fn never_list_families_are_absent() {
        for ns in [
            "attachments",
            "api-keys",
            "auth",
            "email",
            "events",
            "internal",
            "mcp",
            "me",
            "migration",
            "onboarding",
            "passwords",
            "portal",
            "public",
            "secrets",
        ] {
            assert!(
                !families().iter().any(|f| f.namespace == ns),
                "{ns} must never be in the derived catalog"
            );
        }
    }

    #[test]
    fn excluded_paths_stay_out() {
        for path in [
            "/api/assets/{id}/vault",
            "/api/settings/ai/credentials",
            "/api/sign-offs/{id}/payload",
            "/api/admin/quarantine",
            "/api/calendar-sync/feed/{token}",
            "/api/orgs/{org_id}/service-accounts",
        ] {
            assert!(
                !families()
                    .iter()
                    .flat_map(|f| f.tools.iter())
                    .any(|t| t.path == path),
                "{path} must stay out of the catalog"
            );
        }
    }

    /// Conformance: every family and sensitive capability is grantable by the
    /// registry, so an admin grant always names a tool that exists.
    #[test]
    fn every_catalog_capability_is_grantable() {
        for family in families() {
            assert!(
                is_grantable(&family.capability),
                "{} not grantable",
                family.capability
            );
        }
        for cap in sensitive_capabilities() {
            assert!(
                is_grantable(&cap.capability),
                "{} not grantable",
                cap.capability
            );
        }
    }

    #[test]
    fn sensitive_reads_map_to_their_own_capability() {
        let tool = families()
            .iter()
            .flat_map(|f| f.tools.iter())
            .find(|t| t.path == "/api/tickets/{id}/emails")
            .expect("ticket correspondence is a catalog tool");
        assert_eq!(tool.capability, "tickets_correspondence:read");
        assert_eq!(
            capability_for_path("/api/tickets/018f0a5e-0000-7000-8000-000000000000/emails"),
            Some("tickets_correspondence:read")
        );
        assert!(
            families()
                .iter()
                .find(|f| f.namespace == "documents")
                .is_some_and(|f| f.sensitive),
            "documents is marked sensitive (off by default in the admin surface)"
        );
    }

    #[test]
    fn unknown_capabilities_are_refused() {
        for bad in [
            "nonsense:read",
            "nonsense:write",
            "tickets_correspondence:write",
            "tickets",
            "",
        ] {
            assert!(!is_grantable(bad), "{bad} must not be grantable");
        }
        assert!(is_grantable("invoices:read"));
        assert!(is_grantable("tickets_correspondence:read"));
        assert!(
            is_grantable("tickets:write"),
            "the proposal dial stays grantable"
        );
    }
}
